INSERT INTO public.messages (app_id, tenant_id, order_id, sender_type, recipient_type, message_body, is_internal, created_at) VALUES
  ('a0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000001', 'customer', 'thread', 'Hi, can you confirm the cover stock is 250gsm Gloss? I want to make sure it matches our previous order.', false, now() - interval '1 hour'),
  ('a0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000006', 'customer', 'thread', 'Please hold this order — I need to make changes to the report. Will send updated PDF by tomorrow.', false, now() - interval '1 day 2 hours'),
  ('a0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000006', 'admin', 'thread', 'No problem, we''ve placed the order on hold. Just upload the new file when ready and we''ll proceed.', false, now() - interval '1 day'),
  ('a0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000007', 'customer', 'thread', 'This is for our annual gala on the 15th — please ensure the banners are ready well before then!', false, now() - interval '5 hours'),
  ('a0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000010', 'admin', 'thread', 'Pieter, we noticed some alignment issues on sheets 3 and 7 — running QA now. Will update you shortly.', true, now() - interval '10 hours');
